-- generated by gen-purge.cjs — org-4 platform data
\set ON_ERROR_STOP on
\set QUIET 0
\pset pager off
SET client_min_messages TO notice;
\if :apply
\echo '*** APPLY ***'
\else
\echo '*** PLAN (rolls back) ***'
\endif
BEGIN;

DO $$
DECLARE n bigint; total bigint := 0;
BEGIN
  SELECT count(*) INTO n FROM agi_transcripts x
    JOIN agi_sessions v ON v.id = x.session_id
    JOIN agi_engagements e ON e.id = v.engagement_id
   WHERE e.organization_id = 4;
  total := total + n;
  RAISE NOTICE '  [child] % %', rpad('agi_transcripts', 34), n;
  IF __APPLY__ AND n > 0 THEN
    DELETE FROM agi_transcripts WHERE session_id IN (
      SELECT v.id FROM agi_sessions v JOIN agi_engagements e ON e.id = v.engagement_id
       WHERE e.organization_id = 4);
  END IF;

  SELECT count(*) INTO n FROM agi_actions x
    JOIN agi_sessions v ON v.id = x.session_id
    JOIN agi_engagements e ON e.id = v.engagement_id
   WHERE e.organization_id = 4;
  total := total + n;
  RAISE NOTICE '  [child] % %', rpad('agi_actions', 34), n;
  IF __APPLY__ AND n > 0 THEN
    DELETE FROM agi_actions WHERE session_id IN (
      SELECT v.id FROM agi_sessions v JOIN agi_engagements e ON e.id = v.engagement_id
       WHERE e.organization_id = 4);
  END IF;

  -- agi_sessions sits between actions/transcripts and the engagement
  SELECT count(*) INTO n FROM agi_sessions s
    JOIN agi_engagements e ON e.id = s.engagement_id WHERE e.organization_id = 4;
  total := total + n;
  RAISE NOTICE '  [child] % %', rpad('agi_sessions', 34), n;
  IF __APPLY__ AND n > 0 THEN
    DELETE FROM agi_sessions WHERE engagement_id IN (
      SELECT id FROM agi_engagements WHERE organization_id = 4);
  END IF;

  RAISE NOTICE '  [child] subtotal %', total;
END $$;

DO $$
DECLARE t text; n bigint; total bigint := 0;
        tbls text[] := ARRAY['assets', 'asset_tags', 'asset_tag_assignments', 'asset_history', 'asset_relationships', 'asset_candidates', 'discovery_jobs', 'scans', 'scan_jobs', 'scan_work_items', 'scan_results', 'findings', 'report_finding_tracker', 'report_tracker_history', 'assessment_findings', 'assessments', 'code_review_findings', 'vapt_correlated_findings', 'verification_evidence', 'remediation_tasks', 'compliance_evidence', 'reports', 'external_pentest_scopes', 'risks', 'risk_treatments', 'risk_history', 'risk_assessments', 'vapt_campaigns', 'vapt_campaign_steps', 'vapt_approval_requests', 'vapt_mining_patterns', 'vapt_schedules', 'vapt_org_settings', 'agi_engagements', 'agi_decisions', 'agi_engine_invocations', 'agi_capability_confirmations', 'agi_engine_capabilities', 'agi_knowledge_docs', 'agi_knowledge_summaries', 'agi_opencode_jobs', 'agi_skill_outcomes', 'agi_skills', 'agi_tool_install_requests', 'agi_org_agreement_acceptances', 'agi_org_settings', 'agi_org_context_packs', 'agi_org_test_accounts', 'agi_usage_policies', 'ai_agent_runs', 'ai_agent_repo_jobs', 'ai_agent_skills', 'ai_agent_approvals', 'soc_detections', 'soc_cases', 'soc_case_notes', 'alert_events', 'alert_deliveries', 'notifications', 'org_application_logs', 'application_logs', 'platform_events', 'audit_events', 'audit_pending_actions', 'ai_audit_logs', 'server_logs', 'product_projects', 'product_components', 'product_flows', 'product_documents', 'product_confirmations', 'product_clarifications', 'threat_clarifications', 'target_intel_snapshots', 'deployed_agents', 'integration_installations', 'integration_oauth_states', 'organization_integrations', 'github_installations', 'github_repositories', 'github_repository_review_settings', 'scm_credential_targets', 'branch_review_usage_events', 'compliance_assessments', 'compliance_questionnaire_answers', 'compliance_answerer_sessions', 'data_subject_requests', 'service_feedback', 'support_tickets', 'support_ticket_messages', 'funnel_requests', 'access_coupon_redemptions', 'cloud_connectors', 'launch_sandbox_members', 'launch_sandbox_ratings', 'launch_sandbox_update_receipts', 'otp_challenges', 'device_confirm_challenges', 'organization_password_resets', 'organization_user_login_links', 'app_sessions', 'organization_user_sessions'];
        absent int := 0; noorg int := 0; hit int := 0;
BEGIN
  FOREACH t IN ARRAY tbls LOOP
    IF to_regclass('public.' || quote_ident(t)) IS NULL THEN absent := absent + 1; CONTINUE; END IF;
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns
                   WHERE table_schema = 'public' AND table_name = t
                     AND column_name = 'organization_id') THEN
      noorg := noorg + 1;
      RAISE NOTICE '  [skip ] % (no organization_id)', rpad(t, 34);
      CONTINUE;
    END IF;
    EXECUTE format('SELECT count(*) FROM public.%I WHERE organization_id = 4', t) INTO n;
    total := total + n;
    IF n > 0 THEN
      hit := hit + 1;
      RAISE NOTICE '  [rows ] % %', rpad(t, 34), n;
      IF __APPLY__ THEN
        EXECUTE format('DELETE FROM public.%I WHERE organization_id = 4', t);
      END IF;
    END IF;
  END LOOP;
  RAISE NOTICE '  [platform] listed=% absent=% no_org_col=% tables_with_rows=% rows=%',
    array_length(tbls, 1), absent, noorg, hit, total;
END $$;

\if :apply
COMMIT;
\else
ROLLBACK;
\endif
